void rampSoundChannelLocked(s32, s32, s32);  /* extern */

/* Scales a 0-10 volume level to 0-127 and ramps the locked sound channel to it. */ void setSoundChannelVolumeFromLevel(s32 level) {
    rampSoundChannelLocked((((u32)level * 0x7FU) / 10U) & 0xFF, 0, 1);
}
